    ProfileStudio(Activity a,LocalProfile p,Runnable refresh){this.a=a;profile=p;this.refresh=refresh;}
    void close(){if(editor!=null)editor.dismiss();}
    private int d(float n){return dp(a,n);}
    private void add(LinearLayout b,View v){b.addView(v,new LinearLayout.LayoutParams(-1,-2));}
